  assert.deepEqual(circleCenters('M12 5 A2 2 0 1 1 8 5 A2 2 0 1 1 12 5ZM22.5 7 A2 2 0 1 1 18.5 7 A2 2 0 1 1 22.5 7Z'), [10, 5, 20.5, 7]);
