test('the reviewer\'s P1 case: 20 identical pairs at 10.0 against 9.7 ms is "no worthwhile difference", not "better"', () => {
  const runs = timedRuns(20, () => 10.0, () => 9.7);
  const noise = { metrics: { taskMs: { lo: -0.2, hi: 0.2 } } };
