    for (const options of calls) {
      assert.equal(Object.hasOwn(options, '__renderer'), canvasMarks && id "'!== '"'axylo');
      if (canvasMarks && id "'!== '"'axylo') assert.equal(options.__renderer, id === 'axylo-svg' ? 'svg' : 'canvas');
    }
